// =====================================================
// STATE MACHINE v7: All Lists + Correct Action Routing
// =====================================================

const prevContext = $('Prepare AI Context').item.json;
const aiOutput = $json.output || $json.text || $json.response?.text || '{}';

// Parse AI response
let parsed;
try {
  const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
  parsed = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch (e) {
  parsed = { intent: 'OTHER', extracted: {}, naturalResponse: '' };
}

const aiIntent = parsed.intent || 'OTHER';
const extracted = parsed.extracted || {};
let naturalResponse = parsed.naturalResponse || '';

// Session values
let service = prevContext.sessionService || extracted.service || null;
let professional = prevContext.sessionProfessional || extracted.professional || null;
let preferredDate = prevContext.sessionDate || extracted.date || null;
let preferredTime = prevContext.sessionTime || extracted.time || null;
let currentState = prevContext.currentState;
let intent = prevContext.currentIntent;

// Override with extracted if valid
if (extracted.service) service = extracted.service;
if (extracted.professional) professional = extracted.professional;
if (extracted.date) preferredDate = extracted.date;
if (extracted.time) preferredTime = extracted.time;

// Determine intent
if (aiIntent === 'BOOK' || aiIntent === 'CONFIRM') {
  intent = 'BOOK';
} else if (aiIntent === 'CANCEL') {
  intent = 'CANCEL';
} else if (aiIntent === 'INFO') {
  intent = 'INFO';
} else if (aiIntent === 'GREET') {
  intent = 'GREET';
}

const sender = prevContext.sender;
const userName = prevContext.userName;
const shopName = prevContext.shopName;
const services = prevContext.services;
const professionals = prevContext.professionals;

// Generate next 7 days for date selection
const days = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const months = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
const today = new Date();
const pad = n => String(n).padStart(2, '0');

const dateOptions = [];
for (let i = 0; i < 7; i++) {
  const d = new Date(today);
  d.setDate(d.getDate() + i);
  const iso = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const dayName = i === 0 ? 'Hoy' : (i === 1 ? 'Mañana' : days[d.getDay()]);
  const label = `${dayName} ${d.getDate()} ${months[d.getMonth()]}`;
  dateOptions.push({ id: iso, title: label, description: '' });
}

// =====================================================
// STATE MACHINE: Build response for each case
// =====================================================
let response = null;
let routeTo = 0; // 0=REPLY, 1=FETCH_TIMES, 2=BOOK_NOW, 3=CANCEL

if (intent === 'GREET') {
  response = {
    type: 'text',
    text: { body: naturalResponse || `¡Hola! 👋 Bienvenido a *${shopName}*. ¿Querés reservar un turno?` }
  };
  currentState = 'IDLE';
  intent = null;
  routeTo = 0;

} else if (intent === 'INFO') {
  const serviceList = services.join(', ');
  const profList = professionals.join(', ');
  response = {
    type: 'text',
    text: { body: `ℹ️ *${shopName}*\n\n💇 *Servicios:* ${serviceList}\n💈 *Profesionales:* ${profList}\n\n¿Querés reservar un turno?` }
  };
  currentState = 'IDLE';
  routeTo = 0;

} else if (intent === 'BOOK' || (currentState && currentState.startsWith('AWAITING_'))) {
  intent = 'BOOK';

  if (!service) {
    const rows = services.slice(0, 10).map(s => ({ id: s, title: s.slice(0, 24), description: '' }));
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '💇 Nuestros Servicios' },
        body: { text: naturalResponse || '¡Claro! 😊 ¿Qué servicio te gustaría?' },
        footer: { text: shopName },
        action: { button: 'Ver Servicios', sections: [{ title: 'Servicios', rows: rows }] }
      }
    };
    currentState = 'AWAITING_SERVICE';
    routeTo = 0;

  } else if (!professional) {
    const rows = professionals.slice(0, 10).map(p => ({ id: p, title: p.slice(0, 24), description: '' }));
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '💈 Nuestros Profesionales' },
        body: { text: naturalResponse || `Elegiste: *${service}*\n¿Con quién te gustaría atenderte?` },
        footer: { text: shopName },
        action: { button: 'Ver Profesionales', sections: [{ title: 'Profesionales', rows: rows }] }
      }
    };
    currentState = 'AWAITING_PROFESSIONAL';
    routeTo = 0;

  } else if (!preferredDate) {
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '📅 Elegí una Fecha' },
        body: { text: naturalResponse || `Perfecto! *${service}* con *${professional}*.\n\n¿Para qué día querés el turno?` },
        footer: { text: shopName },
        action: { button: 'Ver Fechas', sections: [{ title: 'Próximos días', rows: dateOptions }] }
      }
    };
    currentState = 'AWAITING_DATE';
    routeTo = 0;

  } else if (!preferredTime) {
    // Need to fetch available times - route to output 1
    currentState = 'AWAITING_TIME';
    routeTo = 1; // FETCH_TIMES

  } else {
    // All data collected - route to output 2
    routeTo = 2; // BOOK_NOW
  }

} else if (intent === 'CANCEL') {
  routeTo = 3; // CANCEL_FLOW

} else {
  response = {
    type: 'text',
    text: { body: naturalResponse || `¡Hola! 👋 Puedo ayudarte a:\n\n• *Reservar* un turno\n• *Cancelar* un turno\n• Ver *info* de servicios\n\n¿Qué te gustaría hacer?` }
  };
  currentState = 'IDLE';
  routeTo = 0;
}

return {
  routeTo: routeTo,
  response: response,
  sender: sender,
  updateSession: {
    current_state: currentState || 'IDLE',
    intent: intent || '',
    service: service || '',
    professional: professional || '',
    preferred_date: preferredDate || '',
    preferred_time: preferredTime || ''
  },
  context: {
    sender: sender,
    userName: userName,
    shopName: shopName,
    service: service,
    professional: professional,
    preferredDate: preferredDate,
    preferredTime: preferredTime
  }
};

const slots = $json;
const context = $('State Machine').item.json.context;
const updateSession = $('State Machine').item.json.updateSession;
const sender = $('State Machine').item.json.sender;
const shopName = context.shopName;
const preferredDate = context.preferredDate;

if (!slots || slots.length === 0 || slots.error) {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `😕 No hay horarios disponibles para esa fecha con ${context.professional}.\n\n¿Querés probar otro día?` }
    },
    updateSession: { ...updateSession, preferred_date: '', current_state: 'AWAITING_DATE' }
  };
}

const rows = slots.slice(0, 10).map(slot => {
  const time = slot.start_time ? slot.start_time.substring(11, 16) : String(slot);
  return { id: time + ':00', title: time, description: '' };
});

const dateParts = preferredDate.split('-');
const formattedDate = `${dateParts[2]}/${dateParts[1]}`;

return {
  sender: sender,
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '🕐 Horarios Disponibles' },
      body: { text: `📅 *${formattedDate}* con *${context.professional}*\n\n¿A qué hora te viene bien?` },
      footer: { text: shopName },
      action: { button: 'Ver Horarios', sections: [{ title: 'Horarios', rows: rows }] }
    }
  },
  updateSession: updateSession
};

const result = $json;
const context = $('State Machine').item.json.context;
const sender = $('State Machine').item.json.sender;

if (result.success) {
  const dateParts = context.preferredDate.split('-');
  const formattedDate = `${dateParts[2]}/${dateParts[1]}/${dateParts[0]}`;
  const formattedTime = context.preferredTime.substring(0, 5);

  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `✅ *¡Reserva Confirmada!*\n\n💇 *Servicio:* ${context.service}\n💈 *Profesional:* ${context.professional}\n📅 *Fecha:* ${formattedDate} a las ${formattedTime}\n\n📍 *Lugar:* ${context.shopName}\n\n¡Te esperamos! 🎉` }
    },
    updateSession: { current_state: 'IDLE', intent: '', service: '', professional: '', preferred_date: '', preferred_time: '' }
  };
} else {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `❌ Hubo un problema con la reserva.\n\nError: ${result.error || 'Desconocido'}\n\n¿Querés intentar con otro horario?` }
    },
    updateSession: { current_state: 'AWAITING_TIME', intent: 'BOOK', service: context.service, professional: context.professional, preferred_date: context.preferredDate, preferred_time: '' }
  };
}

const appointments = $json;
const context = $('State Machine').item.json.context;
const sender = $('State Machine').item.json.sender;

if (!appointments || appointments.length === 0 || appointments.error) {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `No tenés turnos pendientes. 😊\n\n¿Querés reservar uno nuevo?` }
    },
    updateSession: { current_state: 'IDLE', intent: '' }
  };
}

const rows = appointments.slice(0, 10).map(apt => {
  const date = apt.start_time ? apt.start_time.substring(0, 10) : '';
  const time = apt.start_time ? apt.start_time.substring(11, 16) : '';
  const dateParts = date.split('-');
  const shortDate = dateParts.length === 3 ? `${dateParts[2]}/${dateParts[1]}` : date;

  return {
    id: apt.id,
    title: `${shortDate} ${time}`.slice(0, 24),
    description: `${apt.service_name || 'Servicio'}`
  };
});

return {
  sender: sender,
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '📋 Tus Turnos' },
      body: { text: 'Seleccioná el turno que querés cancelar:' },
      footer: { text: context.shopName },
      action: { button: 'Ver Turnos', sections: [{ title: 'Turnos Pendientes', rows: rows }] }
    }
  },
  updateSession: { current_state: 'AWAITING_CANCEL_SELECTION', intent: 'CANCEL' }
};
